function solve(lista) {
  return lista.slice().sort((a, b) => {
    const aTokens = a.match(/(\d+)|([^0-9]+)/g) || [];
    const bTokens = b.match(/(\d+)|([^0-9]+)/g) || [];

    const len = Math.min(aTokens.length, bTokens.length);
    for (let i = 0; i < len; i++) {
      const aToken = aTokens[i];
      const bToken = bTokens[i];

      const aIsDigit = /^\d+$/.test(aToken);
      const bIsDigit = /^\d+$/.test(bToken);

      if (aIsDigit && bIsDigit) {
        const aNum = parseInt(aToken, 10);
        const bNum = parseInt(bToken, 10);
        if (aNum !== bNum) return aNum - bNum;
      } else if (aIsDigit) {
        return -1;
      } else if (bIsDigit) {
        return 1;
      } else {
        if (aToken !== bToken) return aToken.localeCompare(bToken);
      }
    }

    return aTokens.length - bTokens.length;
  });
}
